package com.metaplatform.agent.evidence;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.TestPropertySource; import java.math.BigDecimal; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest @TestPropertySource(properties={"spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class ClaimRepositoryTest { @Autowired ClaimRepository repository; @Test void crudAndCustomQuery(){ repository.save(ClaimEntity.builder().claimId("claim-1").runId("run-1").type(ClaimType.FACT).content("c").confidence(BigDecimal.ONE).evidenceRefs("[\"e\"]").generatedByAgentId("a").generatedByModel("m").createdAt(Instant.now()).build()); assertThat(repository.findById("claim-1")).isPresent(); assertThat(repository.findByRunIdOrderByCreatedAtAsc("run-1")).hasSize(1); } }
